: "2b1fb9b4-ed13-4233-a770-703eca3f61e1", "type": "concept", "title": "Parole violations"}, {"id": "b74b6370-e22a-46b4-89c2-5733930ee59f", "type": "concept", "title": "Technical violations"}, {"id": "1152afb2-e6ca-4e8d-99d7-8a039712bd4d", "type": "concept", "title": "Discretionary release"}, {"id": "700e3b59-bf32-418b-a3b4-06f737eea14b", "type": "concept", "title": "Mandatory release"}, {"id": "00ab0001-3744-43c0-9980-e77522b4ad8a", "type": "concept", "title": "Good time"}, {"id": "023aa418-252e-4b51-ad50-2e20c511c664", "type": "concept", "title": "Earned time"}], "description": "The goal is to understand the flow of people into and out of jails, prisons, probation, and parole."}, {"id": "7b22ece1-8e39-413f-886d-de5270b1fa58", "type": "subtopic", "title": "Sentencing equity and policy", "children": [{"id": "b7c8f06c-74a3-420c-9e55-40e63f952081", "type": "concept", "title": "Disparity"}, {"id": "872d9c50-681a-4846-906a-724d93aaeca3", "type": "concept", "title": "Discrimination"}, {"id": "8e7c7ac8-a8d5-4784-ab46-b043460e6677", "type": "concept", "title": "Prosecutorial discretion"}, {"id": "3b850610-300f-449a-9466-306b05a6f5d1", "type": "concept", "title": "Plea bargaining"}, {"id": "52c6c559-ce6b-43e9-93fd-fc14d0100b6b", "type": "concept", "title": "Risk assessment"}, {"id": "916c16cb-fafb-4b0a-b255-b6d28ab70633", "type": "concept", "title": "Guideline departures"}, {"id": "ce01be1e-241b-4d10-913c-8bf799dbdfa6", "type": "concept", "title": "Sentencing commissions"}, {"id": "4c49e2cb-d067-4f47-a967-4e7ae7d212d6", "type": "concept", "title": "Fiscal impact statements"}], "description": "Students examine how sentencing rules create racial, geographic, gender, and class disparities."}]}, {"id": "ab7fed3a-d932-4918-acb9-bb5a01fe4426", "type": "topic", "title": "Corrections Data, Costs, and Policy Analysis", "description": "A serious corrections course must train students to read data rather than rely on slogans. This unit builds literacy in official corrections data, capacity measures, program evidence, and fiscal tradeoffs.", "children": [{"id": "e97f3b55-4172-465e-9714-cb9b8756ebff", "type": "subtopic", "title": "Corrections data sources", "children": [{"id": "713f9168-2a37-4ef2-a364-4acaaf8572a6", "type": "concept", "title": "BJS Corrections"}, {"id": "a76c0511-404d-4a4b-8c47-fc9b0bf69b11", "type": "concept", "title": "National Prisoner Statistics"}, {"id": "0a6b33e5-d603-4661-b534-29258adb19e2", "type": "concept", "title": "Annual Survey of Jails"}, {"id": "ac2fcb69-947c-4751-b050-aab4d08ffbc1", "type": "concept", "title": "Annual Probation Survey"}, {"id": "67bd2724-ebe2-4ed8-aff2-ee98764b376c", "type": "concept", "title": "Annual Parole Survey"}, {"id": "9c53eecb-e505-43be-b04e-c165b91142a6", "type": "concept", "title": "National Corrections Reporting Program"}, {"id": "ff3ced45-0976-44c4-90b0-e417761838e7", "type": "concept", "title": "Survey of Prison Inmates"}, {"id": "cd9fa17f-aa63-4756-8f39-83498165ab9a", "type": "concept", "title": "Corrections Statistical Analysis Tool"}], "description": "Students learn where American corrections data comes from and what each source can and cannot tell us."}, {"id": "52252187-6c87-47ac-9787-5bbf4aaff4c3", "type": "subtopic", "title": "Counting and capacity", "children": [{"id": "7a111ef9-b638-40ca-9ee7-ac58a6523c83", "type": "concept", "title": "Custody population"}, {"id": "6f975ba1-8242-4eb7-bfa6-75c08dea92f1", "type": "concept", "title": "Jurisdiction population"}, {"id": "0b29381f-7a9e-4a46-8d8c-e6163c5799b5", "type": "concept", "title": "Average daily population"}, {"id": "9c467912-9b6c-4431-9a9e-1ca08f8fdaa1", "type": "concept", "title": "Rated capacity"}, {"id": "80ec6978-6d90-4ce2-8e6e-b492cf927332", "type": "concept", "title": "Operational capacity"}, {"id": "40e6ff79-4045-4692-9a9a-d500d50f1e9f", "type": "concept", "title": "Design capacity"}, {"id": "2670cd52-e273-4297-95a1-3ecfff2edae1", "type": "concept", "title": "Crowding"}, {"id": "e4c5f6a0-c625-41ca-ab4c-16eb46b16985", 