update public.learning_paths
set
  title = 'Corrections',
  goal = 'Corrections',
  summary = 'Corrections begins with why society punishes and what institutions are meant to accomplish after conviction or detention. Students study punishment philosophy and the history of American corrections, sentencing structures and population flow, official data and costs, jails and pretrial detention, prison life, administration and staffing, classification and risk-needs assessment, probation, parole, and community supervision, treatment and evidence-based programs, correctional health, inmate rights and conditions litigation, safety and PREA, reentry and recidivism, special populations, capital punishment and life sentences, ethics and leadership, and reform policy design.',
  data = $corrjson${"slug": "corrections", "title": "Corrections", "description": "Corrections begins with why society punishes and what institutions are meant to accomplish after conviction or detention. Students study punishment philosophy and the history of American corrections, sentencing structures and population flow, official data and costs, jails and pretrial detention, prison life, administration and staffing, classification and risk-needs assessment, probation, parole, and community supervision, treatment and evidence-based programs, correctional health, inmate rights and conditions litigation, safety and PREA, reentry and recidivism, special populations, capital punishment and life sentences, ethics and leadership, and reform policy design.", "topics": [{"id": "096768a2-f75d-446f-aa4b-cd4711284f2d", "type": "topic", "title": "Foundations, History, and Philosophy of Punishment", "description": "Corrections begins with the question of why society punishes and what institutions are meant to accomplish after conviction or detention. This unit gives students the philosophical, historical, and system-level language needed for the rest of the course.", "children": [{"id": "56d37721-1f5e-4fd3-a031-b17fc6b57d27", "type": "subtopic", "title": "Punishment theories", "children": [{"id": "ef63d620-6a00-4019-a276-d155afe6a462", "type": "concept", "title": "Retribution"}, {"id": "d30739c4-ad67-4729-958c-5327aba852f6", "type": "concept", "title": "Deterrence"}, {"id": "3328dd5a-32b0-43af-90cb-2488d37d271a", "type": "concept", "title": "Incapacitation"}, {"id": "357f52c3-65f3-41d4-a601-1631a24adf49", "type": "concept", "title": "Rehabilitation"}, {"id": "a6bd8cc8-10c7-41b9-8f37-d8899fd18366", "type": "concept", "title": "Restorative justice"}, {"id": "1409f00f-661a-4d15-b38e-7feea2b72b49", "type": "concept", "title": "Desistance"}, {"id": "4c8ae7f1-5d60-4fb1-9b64-08eaa57a16c0", "type": "concept", "title": "Public safety"}, {"id": "8f4f600e-a787-487b-ac62-40f26c55591f", "type": "concept", "title": "Proportionality"}], "description": "Students learn the main justifications for punishment and how each theory shapes correctional policy."}, {"id": "070fd5ba-32ea-40f3-be28-689c2cc15b4b", "type": "subtopic", "title": "History of American corrections", "children": [{"id": "e0a1c967-6753-4c56-970d-11959e8c2f35", "type": "concept", "title": "Colonial punishments"}, {"id": "e65431a5-0e9c-4181-89b2-52aff6190058", "type": "concept", "title": "Pennsylvania system"}, {"id": "671db859-8f72-4f48-89fa-f97ab5cf37ab", "type": "concept", "title": "Auburn system"}, {"id": "3ac6f512-ce57-4a3f-86a4-7dddc5ee20f6", "type": "concept", "title": "Penitentiary ideal"}, {"id": "5809f452-957a-4a1f-a9d6-c03d4d56d7a9", "type": "concept", "title": "Reformatory movement"}, {"id": "8ba8cc14-f77e-4a4e-ab6e-aeb9eda49415", "type": "concept", "title": "Progressive era"}, {"id": "80b75756-30a9-4d95-a5b9-1d1be2d09f86", "type": "concept", "title": "Medical model"}, {"id": "656ff1f9-8e7d-46de-8eba-de7ede7026f8", "type": "concept", "title": "Nothing works era"}, {"id": "9b40830c-2e8d-4f8c-adae-2e65a7742930", "type": "concept", "title": "Mass incarceration"}], "description": "The point is to see prisons, jails, probation, and parole as historically produced institutions, not natural or fixed arrangements."}, {"id": "a21b65ef-ffd9-4001-9cd8-fbc3a0f92d43", "type": "subtopic", "title": "Correctional system map", "children": [{"id": "72c6e6ef-88ea-4db7-a7bb-891b975be892", "type": "concept", "title": "Pretrial detention"}, {"id": "7c80c065-03a3-4e5c-b85f-33dfd32a06bb", "type": "concept", "title": "Jail"}, {"id": "fd944676-c52b-4f4f-a772-e7e09b8ab700", "type": "concept", "title": "Prison"}, {"id": "fbfc1071-32ae-4748-a808-299c686f9f27", "type": "concept", "title": "Probation"}, {"id": "a8e20147-eb2a-4816-8a86-ef24cd774df7", "type": "concept", "title": "Parole"}, {"id": "41de9e50-3a6f-43db-ba58-49eb0ae2dccd", "type": "concept", "title": "Community corrections"}, {"id": "7782b9eb-f662-40a8-9fef-3e7cc486ab13", "type": "concept", "title": "Reentry"}, {"id": "6e85950a-4b05-4211-9f69-8c26aff1a26c", "type": "concept", "title": "Revocation"}], "description": "Students learn how people move through correctional custody and supervision after arrest, conviction, sentencing, and release."}]}, {"id": "bcc3208a-c099-4b15-8646-5e74be05a7b3", "type": "topic", "title": "Sentencing Structures and Correctional Population Flow", "description": "Sentencing decisions drive correctional populations. This unit connects court decisions, statutes, guidelines, and release mechanisms to admissions, length of stay, and supervision.", "children": [{"id": "60082418-17a4-46e6-8c50-750e004d0210", "type": "subtopic", "title": "Sentencing models", "children": [{"id": "3a67235f-8019-480e-9705-35f6f0322255", "type": "concept", "title": "Indeterminate sentencing"}, {"id": "a4309b93-fe14-4530-8da1-d25dcba64ff8", "type": "concept", "title": "Determinate sentencing"}, {"id": "e3fab330-7f63-402d-b1e3-a2a4b6d3ade4", "type": "concept", "title": "Mandatory minimums"}, {"id": "dda510e2-4c04-4c77-bd21-56844ff64cfc", "type": "concept", "title": "Sentencing guidelines"}, {"id": "d07a8861-0e3e-418e-ac2e-d2c55f96bbfa", "type": "concept", "title": "Habitual offender laws"}, {"id": "c25789fc-e10c-48ef-a448-3ac870c87100", "type": "concept", "title": "Three strikes"}, {"id": "7889340f-99fd-4012-ac11-936bdabcd2f6", "type": "concept", "title": "Truth in sentencing"}, {"id": "ef74bd03-c3e6-413f-a03a-bc9203518b65", "type": "concept", "title": "Split sentences"}], "description": "Students learn how different sentencing structures affect discretion, prison admissions, and time served."}, {"id": "b0c4bc1f-8c06-47a4-8daf-b55dc4260864", "type": "subtopic", "title": "Admissions and release pathways", "children": [{"id": "0e234901-4c6d-4fe2-be6f-3562e03b5608", "type": "concept", "title": "New court commitments"}, {"id": "f1c7b938-6dfc-4445-9a3e-35087dc9fe64", "type": "concept", "title": "Probation violations"}, {"id": "2b1fb9b4-ed13-4233-a770-703eca3f61e1", "type": "concept", "title": "Parole violations"}, {"id": "b74b6370-e22a-46b4-89c2-5733930ee59f", "type": "concept", "title": "Technical violations"}, {"id": "1152afb2-e6ca-4e8d-99d7-8a039712bd4d", "type": "concept", "title": "Discretionary release"}, {"id": "700e3b59-bf32-418b-a3b4-06f737eea14b", "type": "concept", "title": "Mandatory release"}, {"id": "00ab0001-3744-43c0-9980-e77522b4ad8a", "type": "concept", "title": "Good time"}, {"id": "023aa418-252e-4b51-ad50-2e20c511c664", "type": "concept", "title": "Earned time"}], "description": "The goal is to understand the flow of people into and out of jails, prisons, probation, and parole."}, {"id": "7b22ece1-8e39-413f-886d-de5270b1fa58", "type": "subtopic", "title": "Sentencing equity and policy", "children": [{"id": "b7c8f06c-74a3-420c-9e55-40e63f952081", "type": "concept", "title": "Disparity"}, {"id": "872d9c50-681a-4846-906a-724d93aaeca3", "type": "concept", "title": "Discrimination"}, {"id": "8e7c7ac8-a8d5-4784-ab46-b043460e6677", "type": "concept", "title": "Prosecutorial discretion"}, {"id": "3b850610-300f-449a-9466-306b05a6f5d1", "type": "concept", "title": "Plea bargaining"}, {"id": "52c6c559-ce6b-43e9-93fd-fc14d0100b6b", "type": "concept", "title": "Risk assessment"}, {"id": "916c16cb-fafb-4b0a-b255-b6d28ab70633", "type": "concept", "title": "Guideline departures"}, {"id": "ce01be1e-241b-4d10-913c-8bf799dbdfa6", "type": "concept", "title": "Sentencing commissions"}, {"id": "4c49e2cb-d067-4f47-a967-4e7ae7d212d6", "type": "concept", "title": "Fiscal impact statements"}], "description": "Students examine how sentencing rules create racial, geographic, gender, and class disparities."}]}, {"id": "ab7fed3a-d932-4918-acb9-bb5a01fe4426", "type": "topic", "title": "Corrections Data, Costs, and Policy Analysis", "description": "A serious corrections course must train students to read data rather than rely on slogans. This unit builds literacy in official corrections data, capacity measures, program evidence, and fiscal tradeoffs.", "children": [{"id": "e97f3b55-4172-465e-9714-cb9b8756ebff", "type": "subtopic", "title": "Corrections data sources", "children": [{"id": "713f9168-2a37-4ef2-a364-4acaaf8572a6", "type": "concept", "title": "BJS Corrections"}, {"id": "a76c0511-404d-4a4b-8c47-fc9b0bf69b11", "type": "concept", "title": "National Prisoner Statistics"}, {"id": "0a6b33e5-d603-4661-b534-29258adb19e2", "type": "concept", "title": "Annual Survey of Jails"}, {"id": "ac2fcb69-947c-4751-b050-aab4d08ffbc1", "type": "concept", "title": "Annual Probation Survey"}, {"id": "67bd2724-ebe2-4ed8-aff2-ee98764b376c", "type": "concept", "title": "Annual Parole Survey"}, {"id": "9c53eecb-e505-43be-b04e-c165b91142a6", "type": "concept", "title": "National Corrections Reporting Program"}, {"id": "ff3ced45-0976-44c4-90b0-e417761838e7", "type": "concept", "title": "Survey of Prison Inmates"}, {"id": "cd9fa17f-aa63-4756-8f39-83498165ab9a", "type": "concept", "title": "Corrections Statistical Analysis Tool"}], "description": "Students learn where American corrections data comes from and what each source can and cannot tell us."}, {"id": "52252187-6c87-47ac-9787-5bbf4aaff4c3", "type": "subtopic", "title": "Counting and capacity", "children": [{"id": "7a111ef9-b638-40ca-9ee7-ac58a6523c83", "type": "concept", "title": "Custody population"}, {"id": "6f975ba1-8242-4eb7-bfa6-75c08dea92f1", "type": "concept", "title": "Jurisdiction population"}, {"id": "0b29381f-7a9e-4a46-8d8c-e6163c5799b5", "type": "concept", "title": "Average daily population"}, {"id": "9c467912-9b6c-4431-9a9e-1ca08f8fdaa1", "type": "concept", "title": "Rated capacity"}, {"id": "80ec6978-6d90-4ce2-8e6e-b492cf927332", "type": "concept", "title": "Operational capacity"}, {"id": "40e6ff79-4045-4692-9a9a-d500d50f1e9f", "type": "concept", "title": "Design capacity"}, {"id": "2670cd52-e273-4297-95a1-3ecfff2edae1", "type": "concept", "title": "Crowding"}, {"id": "e4c5f6a0-c625-41ca-ab4c-16eb46b16985", "type": "concept", "title": "Length of stay"}], "description": "Students learn why population counts depend on definitions and how capacity measures shape policy debates."}, {"id": "3f9c981f-a152-4f21-9c54-8ad6c646be0c", "type": "subtopic", "title": "Costs and performance", "children": [{"id": "59b2a05e-45ab-4e6a-80e5-6946dd5da7e9", "type": "concept", "title": "Per capita cost"}, {"id": "3d95bc2e-fe76-49b5-8494-148d35b34f5c", "type": "concept", "title": "Marginal cost"}, {"id": "24e78e45-5775-4976-bb5d-66f5c20686df", "type": "concept", "title": "Justice reinvestment"}, {"id": "f9148244-fc86-4596-a6a6-89feab52e82c", "type": "concept", "title": "Cost-benefit analysis"}, {"id": "895301a0-73cf-4000-b8b0-8bd800b740f8", "type": "concept", "title": "Performance measures"}, {"id": "59df0999-d3c2-4a44-b924-e41bc43554a3", "type": "concept", "title": "Program evaluation"}, {"id": "7321e561-a92c-4e68-a310-f4e94a5820d9", "type": "concept", "title": "Recidivism metrics"}, {"id": "743b6c8d-7039-418f-8df5-31e321688f76", "type": "concept", "title": "Equity metrics"}], "description": "The point is to connect public budgets to outcomes, accountability, and opportunity costs."}]}, {"id": "4affff70-b74c-41aa-9167-4f2618e9c9a8", "type": "topic", "title": "Jails, Pretrial Detention, and Local Detention Systems", "description": "Jails are local institutions that hold legally diverse populations: people awaiting trial, people serving short sentences, and people held for other authorities. This unit centers the scale and complexity of jail systems.", "children": [{"id": "4d65206d-d069-445d-95a1-ba6f938a76f7", "type": "subtopic", "title": "Jail roles and populations", "children": [{"id": "f5661d84-0c55-4ead-ad3c-148402545d04", "type": "concept", "title": "Pretrial detainees"}, {"id": "66352df3-3abe-4c20-bf3d-263013d28512", "type": "concept", "title": "Misdemeanor sentences"}, {"id": "232b23d7-5813-4a35-886f-db08706045c0", "type": "concept", "title": "Felony holds"}, {"id": "0baa77d7-f9a4-4a05-bb5e-5e7a37815b2e", "type": "concept", "title": "Bench warrants"}, {"id": "8608af2e-3d5c-4b95-aaf2-c85e20ee5164", "type": "concept", "title": "Immigration detainers"}, {"id": "10d7ce10-97f8-4901-b9e0-b79ad238597b", "type": "concept", "title": "Mental health holds"}, {"id": "dfe5655b-3db4-433e-9307-b79bf6db0125", "type": "concept", "title": "High turnover"}, {"id": "12d1555a-d390-4749-80d1-6c2dc5662237", "type": "concept", "title": "Short length of stay"}], "description": "Students learn how jails differ from prisons in mission, turnover, legal status, and services."}, {"id": "d7f9dd6a-ec87-4612-a99a-1e4053181e45", "type": "subtopic", "title": "Pretrial decision-making", "children": [{"id": "86d10911-833c-42f8-84de-031de96efe2e", "type": "concept", "title": "Cash bail"}, {"id": "aaaf3456-6d0f-4256-ba71-0a78c47bab46", "type": "concept", "title": "Release on recognizance"}, {"id": "ce4ac213-07bf-4d32-a0ce-8a561a00c304", "type": "concept", "title": "Pretrial services"}, {"id": "6092d3ca-a0e1-40a0-94f0-f0e838706952", "type": "concept", "title": "Risk assessment"}, {"id": "bd0137aa-4966-422f-9ef6-ef47b8b199fc", "type": "concept", "title": "Failure to appear"}, {"id": "b06ebeb3-00e9-4d04-9988-4ae737b29285", "type": "concept", "title": "Public safety conditions"}, {"id": "a778d145-9d33-4a0f-bcf8-e578b503c504", "type": "concept", "title": "Preventive detention"}, {"id": "0d959e63-b7c9-4425-9c83-fc7d083f5d53", "type": "concept", "title": "Speedy trial"}], "description": "Students examine how bail, risk assessment, court delay, and detention shape outcomes before conviction."}, {"id": "8fb42e4c-375a-438e-b348-d2e46a3bb6bc", "type": "subtopic", "title": "Jail management and reform", "children": [{"id": "9636a4c3-5acc-4e2d-8bdc-968a450efa6f", "type": "concept", "title": "Booking"}, {"id": "940e093b-e6b0-4eac-ad47-936c24c8aa83", "type": "concept", "title": "Classification"}, {"id": "e0f9cbf4-abc1-440b-8f28-ce839e7b91ad", "type": "concept", "title": "Medical screening"}, {"id": "a89bccb0-799e-4308-aecd-7eb9f6c023ad", "type": "concept", "title": "Suicide prevention"}, {"id": "497783c7-2e5d-44b6-8007-75ec27d7d1fe", "type": "concept", "title": "Jail diversion"}, {"id": "20821f24-ff94-4c20-9e2a-0146c1431f2e", "type": "concept", "title": "Crisis response"}, {"id": "bc460932-5301-44b4-8bd7-d3e7128a8539", "type": "concept", "title": "Population review teams"}, {"id": "89f5f5ec-d731-4ce8-96d8-02eac868abfa", "type": "concept", "title": "Local oversight"}], "description": "The goal is to understand jail crowding, safety, diversion, and local accountability."}]}, {"id": "ee72083a-330d-4d03-b2bb-1b0e0ed43d63", "type": "topic", "title": "Prisons and Prison Life", "description": "Prisons are long-term institutions where law, security, culture, services, deprivation, and human adaptation meet. This unit studies institutional life from the perspective of incarcerated people, staff, administrators, and communities.", "children": [{"id": "fca9832e-728b-4b85-b626-3d7c5d58e827", "type": "subtopic", "title": "Prison types and security levels", "children": [{"id": "682532ab-6cc6-44bc-a836-20e19e68b621", "type": "concept", "title": "Minimum security"}, {"id": "a52c824e-3195-42ac-940c-b1fef563696a", "type": "concept", "title": "Medium security"}, {"id": "d6bc47fe-83f9-445a-ba1f-a7cb5f7ce4f9", "type": "concept", "title": "Maximum security"}, {"id": "2b793328-1ad9-4f8c-b2fe-66d872ee6427", "type": "concept", "title": "Supermax"}, {"id": "5ef3367e-ed92-4b5a-945f-87b0be9afddd", "type": "concept", "title": "Administrative segregation"}, {"id": "3634975c-724e-4f5a-b29b-591beb402686", "type": "concept", "title": "Protective custody"}, {"id": "f289eb79-cd58-450a-a085-62268194cfb4", "type": "concept", "title": "Reception centers"}, {"id": "cfafeb12-2d8f-4dc4-a8c6-bf7983c015cb", "type": "concept", "title": "Private prisons"}], "description": "Students learn how prison design and custody level shape daily life and institutional risk."}, {"id": "5f47ee1f-451f-4b6c-9382-1e8b3e4d2e25", "type": "subtopic", "title": "Prison social order", "children": [{"id": "23916a54-783b-4b7b-930d-3ad1323ef2e9", "type": "concept", "title": "Prisonization"}, {"id": "4702f3ef-ecce-469c-b834-20ee06861e94", "type": "concept", "title": "Inmate subculture"}, {"id": "9a0dc57a-a4ea-4181-a179-23ea4fbdb763", "type": "concept", "title": "Gangs and security threat groups"}, {"id": "a3369d49-d050-4203-b76f-b487d1c9767b", "type": "concept", "title": "Informal economy"}, {"id": "24ca5390-3953-400c-951b-820b29a3861f", "type": "concept", "title": "Contraband"}, {"id": "c44357aa-9ac8-41b5-b0fa-15a231c19b5a", "type": "concept", "title": "Staff-inmate relations"}, {"id": "0ea6b983-3929-4e59-b051-316d8c5acae9", "type": "concept", "title": "Collective behavior"}, {"id": "b3f2e018-ff7b-405a-a36d-c668d9b6f470", "type": "concept", "title": "Grievances"}], "description": "The point is to understand how people adapt to confinement and how informal norms affect safety and legitimacy."}, {"id": "7ec5f2c9-287b-4ddc-adef-57d8ee3af7c7", "type": "subtopic", "title": "Conditions of confinement", "children": [{"id": "e0765cfb-8612-4fba-990d-fefaa6f9ff1c", "type": "concept", "title": "Housing units"}, {"id": "0b99e53b-1f4b-434f-881e-7a8c01fe308a", "type": "concept", "title": "Meals"}, {"id": "0e88ca0f-db5d-437f-a2cc-49763ff2589a", "type": "concept", "title": "Visitation"}, {"id": "c4b84b2b-7a03-4d9d-8b42-9184532e3447", "type": "concept", "title": "Mail"}, {"id": "9c938d35-5b2a-4252-9895-e397e1e88d7c", "type": "concept", "title": "Phones and tablets"}, {"id": "8ffff6bf-ad09-41e6-b495-566cf5cc0fce", "type": "concept", "title": "Work assignments"}, {"id": "b3cc31f5-9d7c-4fd9-88ed-d1125bceaa67", "type": "concept", "title": "Recreation"}, {"id": "6a3d8968-674b-4462-b61e-168a198e954c", "type": "concept", "title": "Religious practice"}, {"id": "ae3ac52a-da41-44e5-97d4-8e08b3b8c051", "type": "concept", "title": "Access to counsel"}], "description": "Students connect facility operations to human dignity, safety, health, programming, and constitutional claims."}]}, {"id": "46c88030-dd29-4819-8736-28a6a20470e6", "type": "topic", "title": "Correctional Administration, Staffing, and Institutional Management", "description": "Corrections is also an administrative field. Students learn how agencies manage staff, budgets, facilities, risk, discipline, classification, emergencies, and organizational culture.", "children": [{"id": "26eb8ce4-746c-4a3e-9ad4-75ddfe9f3a87", "type": "subtopic", "title": "Agency structure and leadership", "children": [{"id": "5145822b-99e1-446d-8e07-972920bb0177", "type": "concept", "title": "Departments of corrections"}, {"id": "c780811f-d1bb-4d1a-aa99-00c4aa8f3d10", "type": "concept", "title": "Wardens"}, {"id": "7284b572-333c-49d4-a675-4088c862db60", "type": "concept", "title": "Sheriffs"}, {"id": "ab890bd8-370f-4305-9ef9-be3ea014300e", "type": "concept", "title": "Jail administrators"}, {"id": "c46d7c59-41b2-4b26-93d1-e7801ee42c95", "type": "concept", "title": "Chain of command"}, {"id": "45cc507e-66ab-463c-84cf-c92ea037d81f", "type": "concept", "title": "Policy directives"}, {"id": "d91b5392-f17a-45f5-8396-985b563c1fb2", "type": "concept", "title": "Accreditation"}, {"id": "3410473d-42cb-453e-a40a-b6453b9e07cb", "type": "concept", "title": "Strategic planning"}], "description": "Students learn how correctional agencies are organized and how leadership choices shape conditions and outcomes."}, {"id": "e47940d3-51c9-4b11-ab8b-2d3b8696ec8c", "type": "subtopic", "title": "Staffing and workforce issues", "children": [{"id": "1943b167-e4f3-4e9a-a1c5-07b60963f3e0", "type": "concept", "title": "Correctional officers"}, {"id": "38344283-5cde-4fba-9370-0f2f23440fe7", "type": "concept", "title": "Case managers"}, {"id": "1a79f883-bfe0-4337-8415-ff27cbcc3a58", "type": "concept", "title": "Medical staff"}, {"id": "1ef401ee-4919-41a6-9265-0f28c1c5c5a5", "type": "concept", "title": "Program staff"}, {"id": "5a69eff5-2815-40be-8063-611048d7f349", "type": "concept", "title": "Vacancy rates"}, {"id": "70823c66-230a-41ce-86f1-f8e0d2e14653", "type": "concept", "title": "Overtime"}, {"id": "1b5c0c89-5e65-4ca1-8023-ca930fc7dcc8", "type": "concept", "title": "Staff wellness"}, {"id": "3ac17651-10e9-4211-af7b-dc51856ccd64", "type": "concept", "title": "Burnout"}, {"id": "17d098ef-f3c4-46b2-8f0c-ea8dab28f96b", "type": "concept", "title": "Training academy"}], "description": "Correctional quality depends heavily on recruitment, training, retention, wellness, and supervision."}, {"id": "7f032ae9-45e5-481a-93aa-5113b268c78c", "type": "subtopic", "title": "Security operations", "children": [{"id": "52d4394c-d75b-4546-93d6-7d8e96ab5ed1", "type": "concept", "title": "Counts"}, {"id": "8ff13cef-5e04-4779-a0a8-26bc8d5afb76", "type": "concept", "title": "Searches"}, {"id": "7dd7e60a-821c-47b7-b75b-2278e1530478", "type": "concept", "title": "Shakedowns"}, {"id": "dc63b53e-29e7-4727-8e19-c1b079416eb9", "type": "concept", "title": "Use of force"}, {"id": "632ecd76-3503-4079-9bcc-43a6a3dc6655", "type": "concept", "title": "Incident command"}, {"id": "53158a81-e2d3-4739-934d-6d0d0cccb66c", "type": "concept", "title": "Emergency response"}, {"id": "be6e15e3-2c1f-4148-8d30-886b5c841b7d", "type": "concept", "title": "Disciplinary hearings"}, {"id": "09a70058-9843-4134-8eaf-f821cb523afb", "type": "concept", "title": "Intelligence gathering"}, {"id": "5b25da81-013e-446e-9193-513c82d40932", "type": "concept", "title": "Contraband control"}], "description": "Students learn the routines that maintain safety and order inside facilities."}]}, {"id": "a0f95df4-0826-46ec-b16c-7347d6c71b33", "type": "topic", "title": "Classification, Risk-Needs Assessment, and Case Management", "description": "Classification and case planning determine where people are housed, what services they receive, and what supervision conditions they face. This unit teaches students to evaluate these tools critically.", "children": [{"id": "f3b2a2f1-3120-415a-85c1-82daa9a211f1", "type": "subtopic", "title": "Custody classification", "children": [{"id": "59e6b809-7137-44dc-87c1-2a65373e6b42", "type": "concept", "title": "Initial classification"}, {"id": "942f1670-c382-45e6-9a6e-60829aa4f859", "type": "concept", "title": "Reclassification"}, {"id": "e8a0bd1b-d881-4cf0-8fe5-a088665451a4", "type": "concept", "title": "Security level"}, {"id": "329dd95b-391e-4280-8d0c-50c1f3dca7ec", "type": "concept", "title": "Escape risk"}, {"id": "dd5ada26-82bd-458a-8d6e-f2e29d1f874e", "type": "concept", "title": "Violence risk"}, {"id": "b36e95eb-27df-484f-8e10-f997ae8e7c5e", "type": "concept", "title": "Protective custody"}, {"id": "7115b80a-cd06-47e6-9bcd-ce241733eccb", "type": "concept", "title": "Special housing"}, {"id": "87eddc77-075f-4cf6-a2a7-2155d43336cd", "type": "concept", "title": "Override decisions"}], "description": "Students learn how agencies sort people by security risk, institutional needs, and housing constraints."}, {"id": "1c0254e4-0b2b-4c24-b64c-3b3fa6a8418d", "type": "subtopic", "title": "Risk-needs-responsivity model", "children": [{"id": "a51bcff8-8f88-48d7-8c1e-ff8e77b6809f", "type": "concept", "title": "Risk principle"}, {"id": "6cd5156a-dbd2-4350-a42e-99141f9878ed", "type": "concept", "title": "Need principle"}, {"id": "3292e8fe-17a2-41f6-bb98-1800ee915a1a", "type": "concept", "title": "Responsivity principle"}, {"id": "945901da-6b95-4dd6-9db9-2cac450df70c", "type": "concept", "title": "Static factors"}, {"id": "8eba2157-0eda-402d-811b-b452098d27bc", "type": "concept", "title": "Dynamic factors"}, {"id": "d9072cdc-e8a9-4090-a604-92504c8875c5", "type": "concept", "title": "Criminogenic needs"}, {"id": "aaa795d4-5005-4b0c-8819-73dc21d26d3a", "type": "concept", "title": "Protective factors"}, {"id": "be30af7c-f658-45c4-9a4a-ec1c864a9d0c", "type": "concept", "title": "Case plan"}], "description": "The goal is to understand evidence-based correctional assessment and its limits."}, {"id": "d651bd3e-115b-47be-86d2-8a84245373c6", "type": "subtopic", "title": "Equity and validation", "children": [{"id": "711ddaba-e975-4cbb-ab59-20ba2af383a6", "type": "concept", "title": "Validation"}, {"id": "ce69660f-4c40-44e1-b970-cb921b169b14", "type": "concept", "title": "Predictive accuracy"}, {"id": "912143a6-b9c1-4f85-b5fe-4a4f72dc3a6d", "type": "concept", "title": "False positives"}, {"id": "33c2efcb-8e14-4d94-8557-275ca3961115", "type": "concept", "title": "False negatives"}, {"id": "36fb671d-c3ee-4b08-b663-f36eb51c81c0", "type": "concept", "title": "Racial bias"}, {"id": "4e0eccca-8f3e-4626-9ea5-3f33b1adb26f", "type": "concept", "title": "Gender responsiveness"}, {"id": "8b103045-31e9-485e-81cb-b74dd420b151", "type": "concept", "title": "Due process"}, {"id": "cd38b626-f3b8-4f77-8557-8f1b7b5f708e", "type": "concept", "title": "Human override"}], "description": "Students learn why assessment tools must be tested for accuracy, bias, transparency, and local fit."}]}, {"id": "8c93b3e9-17b5-4c86-8965-7da87e39afc3", "type": "topic", "title": "Probation, Parole, and Community Corrections", "description": "Most people under correctional control are supervised in the community rather than confined in prison. This unit examines supervision as both social control and service delivery.", "children": [{"id": "68359877-3779-4d29-bc4a-f6fa7e5da895", "type": "subtopic", "title": "Probation and parole foundations", "children": [{"id": "4a892e9b-3a91-4262-b03a-316630eb5645", "type": "concept", "title": "Probation sentence"}, {"id": "6531cc2f-8dc3-4e64-b385-97d964570e56", "type": "concept", "title": "Parole release"}, {"id": "32878894-6b7e-42e9-84ab-4fef7c9f43c1", "type": "concept", "title": "Post-release supervision"}, {"id": "3f621722-dcb7-4d65-84c6-8b1144bdb318", "type": "concept", "title": "Mandatory supervision"}, {"id": "b67122fb-5016-4cff-92d6-7dea07cab6cd", "type": "concept", "title": "Parole boards"}, {"id": "2da2469f-5302-4296-97e9-b29ba48b527c", "type": "concept", "title": "Supervision conditions"}, {"id": "5efb117c-a7ee-4fcf-bbde-067b0b0b3e75", "type": "concept", "title": "Caseloads"}, {"id": "73f53fa2-2577-46ea-a7ff-53c253fb8cf7", "type": "concept", "title": "Technical violations"}], "description": "Students learn the differences among probation, parole, and other supervision statuses."}, {"id": "36129ee9-9b50-4df4-86a9-344bd52c7d56", "type": "subtopic", "title": "Supervision practice", "children": [{"id": "c170c1ad-18bc-49b7-883d-3a22b3663d25", "type": "concept", "title": "Home visits"}, {"id": "632d4ba5-efb6-47c3-b890-48d22716d618", "type": "concept", "title": "Office contacts"}, {"id": "742b9acb-308b-4989-9f18-ad34f79152e6", "type": "concept", "title": "Drug testing"}, {"id": "e29ca09b-38dc-46c6-808f-5931983ac7fd", "type": "concept", "title": "Electronic monitoring"}, {"id": "1ebbcb24-d0a5-424e-b908-df91f628004c", "type": "concept", "title": "Graduated sanctions"}, {"id": "0a1556ee-0bb1-48a3-a480-5c8f43cfd898", "type": "concept", "title": "Incentives"}, {"id": "56c52d6d-c65e-4fe4-8c93-00fd6cdc9bbf", "type": "concept", "title": "Motivational interviewing"}, {"id": "7c61149d-9005-4343-8a0d-c7db3da2b9f9", "type": "concept", "title": "Swift, certain, and fair sanctions"}], "description": "Students examine what officers do and how supervision can either support change or deepen system involvement."}, {"id": "7ee9ea93-af48-4342-8315-4c404cc48e51", "type": "subtopic", "title": "Community correctional options", "children": [{"id": "b3e66d7c-e9f4-4a5a-841c-7757a7d328f9", "type": "concept", "title": "Day reporting centers"}, {"id": "8a8bc456-6514-4963-b47d-d08fa91fa326", "type": "concept", "title": "Halfway houses"}, {"id": "dfb8194e-0d64-4510-bb3b-00acdceb4ae6", "type": "concept", "title": "Residential reentry centers"}, {"id": "a5b8f7e2-3ee8-438e-bfa2-209fb77d00af", "type": "concept", "title": "Work release"}, {"id": "23f566e8-9849-4215-be26-db212763f82c", "type": "concept", "title": "Problem-solving courts"}, {"id": "f68cd112-47a2-49a1-aeb0-ea201894fb47", "type": "concept", "title": "Community service"}, {"id": "5d03a30a-c224-41ee-94ba-809d062e612c", "type": "concept", "title": "Restorative programs"}, {"id": "faf55a97-1818-4ad6-a0db-70367753b7a2", "type": "concept", "title": "Treatment courts"}], "description": "The point is to understand intermediate sanctions and local alternatives to incarceration."}]}, {"id": "92b0bfc1-d54a-4bb3-808d-62f893888812", "type": "topic", "title": "Treatment, Rehabilitation, Education, and Evidence-Based Programs", "description": "Rehabilitation asks what corrections can do to reduce harm and support lawful, stable lives. Students learn to distinguish program labels from evidence-based practice.", "children": [{"id": "adcfe37f-c13f-4915-b488-2a8204d24aab", "type": "subtopic", "title": "Program types", "children": [{"id": "4a6e881c-8b39-41c6-994a-cfd9044c41ed", "type": "concept", "title": "Cognitive behavioral therapy"}, {"id": "00ab6980-01ac-4afc-b17a-95b911f16ac9", "type": "concept", "title": "Substance use treatment"}, {"id": "ae6af32e-60a4-4f78-86db-033180a36b83", "type": "concept", "title": "Educational programs"}, {"id": "837d65b3-9397-41f6-9de8-f9f86beb0a4f", "type": "concept", "title": "GED and literacy"}, {"id": "9aeae347-f216-4af1-a800-3aab575b6ff5", "type": "concept", "title": "Vocational training"}, {"id": "ac793077-9b4e-4b10-9cc6-b3e51c2b00f3", "type": "concept", "title": "College in prison"}, {"id": "6893d92d-b96d-4591-ae10-74db83c28cf2", "type": "concept", "title": "Anger management"}, {"id": "e3b6f1d0-35aa-4c51-852a-527847a74de6", "type": "concept", "title": "Family programs"}], "description": "Students learn the major categories of correctional programming and their intended outcomes."}, {"id": "2fec6b29-02a8-4388-aa91-350f29a914a7", "type": "subtopic", "title": "Evidence and implementation", "children": [{"id": "251746ef-312a-4d13-a2ec-d18b97df7833", "type": "concept", "title": "Program fidelity"}, {"id": "509d4d5f-3d85-40dc-9cdf-f5c44ea04de7", "type": "concept", "title": "Dosage"}, {"id": "1a70a467-7192-4c65-ba36-63b244fcb830", "type": "concept", "title": "Eligibility"}, {"id": "27345ffa-07e6-4093-b1e2-1f6ecc542cfa", "type": "concept", "title": "Completion"}, {"id": "56686f89-c8a4-4b3d-972d-1606e346432a", "type": "concept", "title": "Process evaluation"}, {"id": "c6fc0e73-02ef-4254-aafb-f7bb71ec47fc", "type": "concept", "title": "Outcome evaluation"}, {"id": "1be0420c-8985-4d86-87e6-4bf36ca3e80c", "type": "concept", "title": "Randomized trials"}, {"id": "79d5fe50-c3f8-4de7-8e06-642abe2fc760", "type": "concept", "title": "Quasi-experimental designs"}, {"id": "f31458c6-01ac-491d-9a9c-4d891839eaba", "type": "concept", "title": "CrimeSolutions ratings"}], "description": "Students learn why program quality, targeting, fidelity, and dosage matter."}, {"id": "47abb6d0-9845-4838-a1a4-56b29ca4e3d5", "type": "subtopic", "title": "Barriers to access", "children": [{"id": "d6c16428-2328-40a6-88dd-76d7d000cc7f", "type": "concept", "title": "Waitlists"}, {"id": "ce7cfed6-12f0-4d93-9377-8d9549b13f87", "type": "concept", "title": "Staff shortages"}, {"id": "58680c90-cab1-4ad6-ac01-e880e4884a71", "type": "concept", "title": "Transfers"}, {"id": "8f1461b8-2214-4c9c-844c-98e8b678befc", "type": "concept", "title": "Disciplinary exclusions"}, {"id": "b766a981-c3d3-496b-9921-075f933b5b05", "type": "concept", "title": "Language access"}, {"id": "fcb51ff7-98e1-42ca-9684-54d4ce95d652", "type": "concept", "title": "Disability access"}, {"id": "2737c85a-a23c-43ce-ae4c-b00f162d99a0", "type": "concept", "title": "Technology limits"}, {"id": "8ce7d464-0947-44fd-afe0-edbbdb94562a", "type": "concept", "title": "Release timing"}], "description": "The goal is to identify practical constraints that keep programs from reaching people who need them."}]}, {"id": "a376e57a-9104-44ad-af35-679274653543", "type": "topic", "title": "Correctional Health, Mental Health, Substance Use, and Disability", "description": "Correctional systems are major providers of health, mental health, and substance use services. Students learn the legal, ethical, and operational stakes of care in custody and supervision.", "children": [{"id": "0ccacf7d-a55d-4336-a6bb-2499c517f1b6", "type": "subtopic", "title": "Health care in custody", "children": [{"id": "80f97de2-5cac-4279-adf0-99dd5ba5db2f", "type": "concept", "title": "Intake screening"}, {"id": "201bcd23-9abf-4877-98a7-c179e97735f2", "type": "concept", "title": "Chronic care"}, {"id": "179bc482-2505-4446-b4e7-37d5f0269858", "type": "concept", "title": "Medication continuity"}, {"id": "5909cdc6-5d4a-4c33-b706-3dd29b1ccf57", "type": "concept", "title": "Dental care"}, {"id": "69a8f5c7-4fc4-42d1-9e94-82f0c4b1c2a6", "type": "concept", "title": "Infectious disease"}, {"id": "cd519e44-b97c-4cd7-8c58-ee33495a9ee5", "type": "concept", "title": "Pregnancy care"}, {"id": "2fb8fe69-9091-47fc-a615-9dcbb7b9e289", "type": "concept", "title": "Aging prisoners"}, {"id": "6b10b055-1707-4178-8450-a703e53476f3", "type": "concept", "title": "Telehealth"}], "description": "Students learn the basic duty to provide care and the operational challenges of doing so."}, {"id": "6d696ab6-4a99-49a7-bd60-73b46fe796e7", "type": "subtopic", "title": "Mental health and suicide prevention", "children": [{"id": "71964049-bb17-4ffc-b6fb-0d2171446db4", "type": "concept", "title": "Serious mental illness"}, {"id": "b47f4e49-2897-4810-950e-9c00f8a322e1", "type": "concept", "title": "Crisis intervention"}, {"id": "b56f8de3-0f55-477a-a3bd-852f253bb27c", "type": "concept", "title": "Suicide screening"}, {"id": "2b1dd983-3a79-4e97-96f9-d35fcd39ecdd", "type": "concept", "title": "Observation cells"}, {"id": "ef361e56-6438-45a0-8299-59bef95982cc", "type": "concept", "title": "Competency issues"}, {"id": "c90f6948-3612-4959-ba7d-83e52e176f31", "type": "concept", "title": "Trauma"}, {"id": "3c5420e5-67cf-48c9-b733-e0c17b4edad9", "type": "concept", "title": "Co-occurring disorders"}, {"id": "42233f50-a002-4638-b556-7a234678e14e", "type": "concept", "title": "Discharge planning"}], "description": "The point is to connect behavioral health needs to safety, discipline, segregation, and reentry."}, {"id": "c4a0b283-c775-4440-b2b8-ba0cef080e91", "type": "subtopic", "title": "Substance use and disability", "children": [{"id": "860e3e29-1481-480f-9204-48b98e03a47a", "type": "concept", "title": "Medication-assisted treatment"}, {"id": "d9c296c5-2ad4-4d57-a055-dc3b5504cc96", "type": "concept", "title": "Opioid use disorder"}, {"id": "265c6064-2615-4a18-84d5-db8befdada7b", "type": "concept", "title": "Withdrawal management"}, {"id": "20d2c0a4-f7bb-46aa-94b6-d1bc37c925fa", "type": "concept", "title": "ADA accommodations"}, {"id": "45188db2-427a-4400-bf64-928a35d20fa5", "type": "concept", "title": "Intellectual disability"}, {"id": "6d8eaa5a-8d7b-4486-abbf-bf8748dc5530", "type": "concept", "title": "Deaf and hard of hearing access"}, {"id": "c421d9b2-822e-48d9-a0c4-760b1042b1dc", "type": "concept", "title": "Mobility access"}, {"id": "09d0caad-cf88-4bc2-8981-2639dea1147d", "type": "concept", "title": "Continuity of care"}], "description": "Students examine treatment, accommodation, and continuity of care as core correctional issues."}]}, {"id": "87f7b16e-4fba-4437-9a3c-e81b787452d4", "type": "topic", "title": "Inmate Rights, Correctional Law, and Conditions Litigation", "description": "Correctional law defines the constitutional floor under conditions of confinement and community supervision. Students learn the doctrines that govern rights, remedies, and institutional deference.", "children": [{"id": "d57a69dd-cc8f-4ce5-a7d7-3439a6e3faa0", "type": "subtopic", "title": "Constitutional foundations", "children": [{"id": "0fce9ee9-607f-4530-9777-6aa725a90dce", "type": "concept", "title": "Eighth Amendment"}, {"id": "6432c9cb-34ce-4d2d-a450-995c025724e1", "type": "concept", "title": "Fourteenth Amendment"}, {"id": "186815c8-c999-4671-8f1b-a988d02ab714", "type": "concept", "title": "First Amendment"}, {"id": "5e58629d-8f71-4953-9f9b-9638bb5813bc", "type": "concept", "title": "Fourth Amendment"}, {"id": "845f1243-6555-408f-8ed4-6b2a16c870d0", "type": "concept", "title": "Due process"}, {"id": "e4282daa-7a29-4130-ac58-2e820557cc4c", "type": "concept", "title": "Equal protection"}, {"id": "9d5bc603-d23e-4d68-870c-d4aab8b7fc77", "type": "concept", "title": "Access to courts"}, {"id": "451f9fa9-0fe4-4fb0-82cd-45fa56e63325", "type": "concept", "title": "Religious exercise"}], "description": "Students learn how different amendments apply to convicted prisoners, pretrial detainees, and supervised people."}, {"id": "43deb274-784b-4a29-89a4-d1adb23167c2", "type": "subtopic", "title": "Rights and restrictions", "children": [{"id": "14ab0dd1-ccc2-4f3d-bfd7-c6d4c825726e", "type": "concept", "title": "Medical care"}, {"id": "6a5cca2f-bb11-4609-9c1f-0985cf941c77", "type": "concept", "title": "Use of force"}, {"id": "114785b6-2e7f-438d-b1b3-75f22b437709", "type": "concept", "title": "Solitary confinement"}, {"id": "e5650fee-e1e4-44f2-a781-9eacddb1ae7e", "type": "concept", "title": "Discipline"}, {"id": "0be4f548-3a67-41aa-9e7d-0f903f626bcb", "type": "concept", "title": "Mail and speech"}, {"id": "8cc80d71-b8de-450e-858b-e28670cfceb0", "type": "concept", "title": "Visitation"}, {"id": "d2283e90-e493-4b2a-93b3-7da28815c2cc", "type": "concept", "title": "Searches"}, {"id": "382141f0-b8b8-412f-ac10-50dc84496c35", "type": "concept", "title": "Grievance systems"}, {"id": "fb14c0e8-ba42-4a41-b4f6-b5ae20223592", "type": "concept", "title": "Retaliation"}], "description": "The goal is to understand how courts balance institutional security against individual rights."}, {"id": "85d108d1-b711-4db7-9f31-e3388e1c2399", "type": "subtopic", "title": "Litigation and remedies", "children": [{"id": "704ed334-2c2c-4b92-bf2c-f1e34ed55131", "type": "concept", "title": "Section 1983"}, {"id": "a8f93444-bf35-4657-a83c-ceedbc27657d", "type": "concept", "title": "Bivens"}, {"id": "f1f89f1a-b095-473b-bf98-5e40ef625757", "type": "concept", "title": "PLRA exhaustion"}, {"id": "52b41b1d-f38a-4224-b0a0-7739a51fd80c", "type": "concept", "title": "Consent decrees"}, {"id": "eea76794-f5dd-4599-8ebb-dd17074a2373", "type": "concept", "title": "Injunctions"}, {"id": "2a988672-4d14-4d73-946e-142c445b7af1", "type": "concept", "title": "Damages"}, {"id": "0b0685a7-1f21-4f25-8d5b-0b18bc1b94a3", "type": "concept", "title": "Qualified immunity"}, {"id": "dad4424f-8604-4cfa-b3b6-cb866ba7169a", "type": "concept", "title": "Class actions"}, {"id": "878adfab-632e-434c-b892-1d7c656abf3f", "type": "concept", "title": "Monitoring"}], "description": "Students learn the procedural barriers and remedial tools in corrections litigation."}]}, {"id": "b57e28c3-c255-4451-a015-544ccdbc565d", "type": "topic", "title": "Safety, PREA, Use of Force, and Institutional Accountability", "description": "Safety is not only custody control; it includes protection from abuse, transparent reporting, fair investigations, and accountable uses of power. This unit centers staff and resident safety together.", "children": [{"id": "a49e073c-0e9b-48be-9b17-a30eb0e0fcdc", "type": "subtopic", "title": "PREA and sexual safety", "children": [{"id": "73631758-f66c-46fd-bb55-5d1aebd7eb19", "type": "concept", "title": "PREA standards"}, {"id": "925f30cf-40a3-49ad-a2f2-eeb6e7f0ef8f", "type": "concept", "title": "Screening"}, {"id": "3bafe59a-d2d2-4fe5-8849-ffd9846b4b5e", "type": "concept", "title": "Reporting channels"}, {"id": "997b07e2-8f65-4e40-a60c-a91119705fdd", "type": "concept", "title": "Retaliation protection"}, {"id": "91f0f84b-ad00-42a3-b299-12335e6920f1", "type": "concept", "title": "Victim services"}, {"id": "77089293-44e2-4b6b-9a52-30bf92ec72e0", "type": "concept", "title": "Investigations"}, {"id": "55d23b5a-4e8b-46df-add5-dffc33db1b01", "type": "concept", "title": "Audit instruments"}, {"id": "a684b69e-c3bc-4e23-bec0-c1636ed9628d", "type": "concept", "title": "Corrective action"}], "description": "Students learn the role of PREA standards, prevention, reporting, investigations, and audits in confinement settings."}, {"id": "91a03636-3d2b-4afb-b490-f38128b646da", "type": "subtopic", "title": "Use of force and discipline", "children": [{"id": "6e8810f4-7f21-48d6-add7-9540d4812019", "type": "concept", "title": "Continuum of force"}, {"id": "7c4711e7-360c-48dc-b0f3-8ee421f82cf6", "type": "concept", "title": "Chemical agents"}, {"id": "8f2ca974-18a8-44b3-90cf-72883de4a83f", "type": "concept", "title": "Restraints"}, {"id": "c7d0f283-06a6-43a0-9f8b-6ab1c0340098", "type": "concept", "title": "Cell extractions"}, {"id": "43c919cb-8b47-4bd7-a4af-ca19f9e0bd76", "type": "concept", "title": "Body cameras"}, {"id": "ab51ec88-719b-4853-8a8b-36b4c7159ada", "type": "concept", "title": "Incident reports"}, {"id": "43a3784f-fabd-4b63-bb61-1bab55cf0b05", "type": "concept", "title": "Disciplinary segregation"}, {"id": "9237a9fc-dcea-47c4-b846-079f28ae5d3e", "type": "concept", "title": "Due process hearings"}], "description": "The point is to evaluate when force is authorized and how agencies document, review, and reduce it."}, {"id": "f8f2ab1d-04a1-4a91-8b7a-56613854f7e5", "type": "subtopic", "title": "Oversight and accountability", "children": [{"id": "0d1eaad6-c7db-4abe-96e4-95f751204dea", "type": "concept", "title": "Internal affairs"}, {"id": "2aeabe13-c5b4-4376-b615-7a4010ca63bd", "type": "concept", "title": "Inspector general"}, {"id": "54922067-b476-4896-8cd9-c082c3463580", "type": "concept", "title": "Ombuds"}, {"id": "76638256-994b-4852-8e28-57fc4a48d013", "type": "concept", "title": "Accreditation"}, {"id": "00f073c8-8334-40c6-bf97-c9088ca62e11", "type": "concept", "title": "Civilian oversight"}, {"id": "9ee99962-7041-450d-8879-598b76d9ea5d", "type": "concept", "title": "Mortality review"}, {"id": "f94095c7-bdd9-47b5-8539-db5dc56e7436", "type": "concept", "title": "Data transparency"}, {"id": "a977f1f9-90c8-4153-ac47-57df24cbba9b", "type": "concept", "title": "Whistleblower protection"}], "description": "Students learn how internal and external oversight can identify systemic problems."}]}, {"id": "95feecd9-b1df-4ad7-85fe-b4851a57b6ff", "type": "topic", "title": "Reentry, Desistance, and Recidivism", "description": "Reentry begins before release and continues after return to the community. Students learn how housing, work, supervision, family, treatment, and legal barriers shape desistance.", "children": [{"id": "c5e632ee-fd4f-4d29-aca6-fa9b451432fd", "type": "subtopic", "title": "Release planning", "children": [{"id": "b511b928-22c7-44a7-9ba2-32ade9276ac5", "type": "concept", "title": "Discharge planning"}, {"id": "0882a189-df9c-4bad-a4ec-881d4c02f243", "type": "concept", "title": "Identification documents"}, {"id": "ffc46b40-a80a-4f66-a165-4c90beab144a", "type": "concept", "title": "Medications"}, {"id": "f9a94c49-14bd-4f88-ba4e-32112aac4b64", "type": "concept", "title": "Benefits enrollment"}, {"id": "aefe352b-3800-4bf4-89b2-4eeaf55334a8", "type": "concept", "title": "Housing plan"}, {"id": "f9222a6c-4c23-4151-ac56-e601f52744f6", "type": "concept", "title": "Employment plan"}, {"id": "975063f7-56e2-43dd-a946-108292e22b91", "type": "concept", "title": "Family reunification"}, {"id": "09d6f681-0a00-4992-95ca-fc35e0819670", "type": "concept", "title": "Transportation"}], "description": "Students learn what a practical reentry plan must address before someone leaves custody."}, {"id": "0b277b28-23da-404b-a1fa-dcf8930aa9a8", "type": "subtopic", "title": "Recidivism and desistance", "children": [{"id": "128bd644-8639-4db0-9af3-59e64f05895e", "type": "concept", "title": "Rearrest"}, {"id": "84c3be04-64a9-461e-8c61-68bc5a2b610d", "type": "concept", "title": "Reconviction"}, {"id": "897e0875-a592-4fd5-892d-9657a80aaf4e", "type": "concept", "title": "Reincarceration"}, {"id": "39308e25-d6f1-4a69-88cd-fe39d3c56f16", "type": "concept", "title": "Technical violation"}, {"id": "73603927-e944-410d-98ab-37806088b89e", "type": "concept", "title": "Follow-up period"}, {"id": "c49cca3d-b8fa-4f97-9452-9bfc55b4cec9", "type": "concept", "title": "Desistance"}, {"id": "81a647da-62b8-4bd7-a6c5-ab7040a56187", "type": "concept", "title": "Social bonds"}, {"id": "88b948d1-331e-49a5-922c-e130ddc6578d", "type": "concept", "title": "Identity change"}, {"id": "1c08a15a-8b3d-46db-a4c8-e026bba1d1b4", "type": "concept", "title": "Procedural justice"}], "description": "The goal is to understand recidivism metrics and the broader process of leaving crime behind."}, {"id": "f8325171-6b89-44fb-b850-33f64406a1dd", "type": "subtopic", "title": "Collateral consequences", "children": [{"id": "92c6ee4f-ad25-42a4-90fb-2791a587d336", "type": "concept", "title": "Criminal records"}, {"id": "d7ccad72-5ff7-492f-8789-d106b6e40c92", "type": "concept", "title": "Expungement"}, {"id": "4f7ff2b9-f92c-4781-b8f4-6d3cc9489c08", "type": "concept", "title": "Occupational licensing"}, {"id": "d12b1003-ac36-498c-9808-833af32e1369", "type": "concept", "title": "Voting rights"}, {"id": "6d1f8f6f-e372-4eb7-b7c4-0adc1e8c74e0", "type": "concept", "title": "Public housing"}, {"id": "82f0a8a4-df28-42a2-bc0c-273fe435fcb5", "type": "concept", "title": "Student aid"}, {"id": "dfd09b4c-698e-4583-9bef-3c5a15d35b60", "type": "concept", "title": "Child support"}, {"id": "2a3ce95c-9ae6-4d0a-a0df-bf3dab7fa920", "type": "concept", "title": "Driver licenses"}], "description": "Students examine how legal and social barriers can undermine reintegration."}]}, {"id": "67552458-ca16-491b-9426-d127b4d26f8b", "type": "topic", "title": "Special Populations, Equity, and Human Dignity", "description": "Correctional systems house and supervise people with very different risks, needs, histories, and legal protections. This unit pushes students to think beyond average cases.", "children": [{"id": "e8c623d9-4e08-41bf-91cf-109040f31378", "type": "subtopic", "title": "Race, ethnicity, class, and geography", "children": [{"id": "b8718a22-d5c2-46d9-85ab-7c8a9aa3f260", "type": "concept", "title": "Racial disparity"}, {"id": "733e63dc-9883-4523-8048-806909085965", "type": "concept", "title": "Native and tribal justice"}, {"id": "63d65058-fc5d-46da-8ea2-7ddd831c639b", "type": "concept", "title": "Rural corrections"}, {"id": "0979a7e4-f751-459c-84a0-d80f4e6b285e", "type": "concept", "title": "Urban jail systems"}, {"id": "476c8239-ec7f-480b-864a-4698a1e1f422", "type": "concept", "title": "Poverty"}, {"id": "9302cb8c-38f4-451b-b593-4dbe086821ae", "type": "concept", "title": "Fines and fees"}, {"id": "2580aafd-a6a7-412c-bf32-81ea087b4b88", "type": "concept", "title": "Language access"}, {"id": "fd9bcdfa-59c2-4feb-b146-6a80e1ca703d", "type": "concept", "title": "Immigration status"}], "description": "Students examine how inequality appears in admission, classification, discipline, programming, release, and supervision outcomes."}, {"id": "9520f702-c8ba-4038-884c-e87caca6ed03", "type": "subtopic", "title": "Gender, sexuality, and family status", "children": [{"id": "5756cb64-315b-4e57-85d4-6154ba405e0f", "type": "concept", "title": "Women in custody"}, {"id": "6f0f0557-71e1-48c1-82ad-6eaf8dd27a16", "type": "concept", "title": "Pregnancy"}, {"id": "5b37747b-b0f3-4804-a7bb-9618e42b96a3", "type": "concept", "title": "Parenting programs"}, {"id": "4c3cd1a6-3e15-40b7-b7d3-bcf2a69320ad", "type": "concept", "title": "Transgender people"}, {"id": "0a1b9d1a-6521-4540-879e-cbf014e061f6", "type": "concept", "title": "LGBTQ+ safety"}, {"id": "599b67d0-e2e1-40a5-ad47-ff94edecaf74", "type": "concept", "title": "Search policies"}, {"id": "eb14fcbb-c142-46fe-9df6-f7f5323f8e22", "type": "concept", "title": "Housing decisions"}, {"id": "42bb2b42-0c1a-4ff7-ab60-b903a031180f", "type": "concept", "title": "Family contact"}], "description": "The goal is to understand gender-responsive and LGBTQ+ responsive correctional practice."}, {"id": "c2cadca6-ac72-4e12-9708-3a66517c2e5d", "type": "subtopic", "title": "Age, disability, and vulnerability", "children": [{"id": "c0815caa-7cf3-4802-ab16-35042de47777", "type": "concept", "title": "Youth in adult facilities"}, {"id": "3bab3fc1-8f48-45fb-bdfa-be7bf3b63056", "type": "concept", "title": "Emerging adults"}, {"id": "6962036c-f3e6-4b18-96f9-f0a3ec8bb28e", "type": "concept", "title": "Older prisoners"}, {"id": "4dbe5354-bd2f-495f-abd4-0760b1626c63", "type": "concept", "title": "Disability accommodations"}, {"id": "54fcab38-95f6-4193-85ac-e46576b9d40e", "type": "concept", "title": "Protective custody"}, {"id": "9c026ec4-528b-49ce-85be-ced5fcec0b88", "type": "concept", "title": "Victimization risk"}, {"id": "0c6b1fc0-cdae-4272-a855-2c82be1fdf93", "type": "concept", "title": "Long-term care"}, {"id": "9ccbdce6-3d82-4c5d-8af5-039499e5d2ec", "type": "concept", "title": "Compassionate release"}], "description": "Students learn how age and vulnerability change risk, care, safety, and release planning."}]}, {"id": "79834157-1665-47d9-82bc-c35833884f9c", "type": "topic", "title": "Capital Punishment, Life Sentences, and Extreme Punishment", "description": "Capital punishment and life sentences reveal the sharpest moral, legal, racial, and administrative questions in corrections. Students study both death penalty systems and long-term confinement.", "children": [{"id": "81bc43de-01bc-4cb4-baf2-e5c5cfd26510", "type": "subtopic", "title": "Capital punishment process", "children": [{"id": "e29683e6-cdb5-4f2c-b91e-17beacbc0143", "type": "concept", "title": "Capital charging"}, {"id": "2fd0a6de-0825-4c74-9cb7-3dae56dc977c", "type": "concept", "title": "Aggravating factors"}, {"id": "e1978ff2-d299-482c-8f17-514603ebe2d5", "type": "concept", "title": "Mitigating evidence"}, {"id": "23f59415-4522-4275-9625-ac4affbcd259", "type": "concept", "title": "Penalty phase"}, {"id": "79cc98fd-c6ee-4dd7-826b-8f147f249a32", "type": "concept", "title": "Direct appeal"}, {"id": "a79f1b6b-effd-4d6a-8320-f74f452e3034", "type": "concept", "title": "Post-conviction review"}, {"id": "0110401b-1443-44fe-9e50-f9fc1c9cb7d7", "type": "concept", "title": "Habeas corpus"}, {"id": "0d8e2fdb-e15e-4dec-8003-98de785214e0", "type": "concept", "title": "Execution protocols"}], "description": "Students learn the stages and legal safeguards in American death penalty administration."}, {"id": "21182a0b-ad75-4593-af1d-a490323e447f", "type": "subtopic", "title": "Death row and execution administration", "children": [{"id": "c641c3ee-2338-4c26-a8ae-ac2dce83be1e", "type": "concept", "title": "Death row housing"}, {"id": "a78d084f-d758-4861-b6ac-98e47abe1989", "type": "concept", "title": "Isolation"}, {"id": "ec5ffb2a-62fd-4e79-9627-5f3a19a51e54", "type": "concept", "title": "Spiritual advisors"}, {"id": "33518bb5-92ac-459a-bcca-990b12271f38", "type": "concept", "title": "Medical ethics"}, {"id": "9881d3c9-7ef0-465d-a041-3fd8101c585b", "type": "concept", "title": "Lethal injection"}, {"id": "eb84a2d2-823f-456e-bc6e-df36522d7478", "type": "concept", "title": "Victim family notification"}, {"id": "0fb8696a-60a2-46ab-bcbe-8ec4ff9eda6c", "type": "concept", "title": "Last statements"}, {"id": "5c61c51a-7393-43f4-9a23-bda08da5000b", "type": "concept", "title": "Execution witnesses"}], "description": "The point is to understand how capital punishment becomes a correctional management problem."}, {"id": "4e98a1d3-df8c-4e7b-b98f-d43667176918", "type": "subtopic", "title": "Life and long-term sentences", "children": [{"id": "f456d589-5c9d-4e5f-886a-62b58effebfc", "type": "concept", "title": "Life without parole"}, {"id": "3bb37ace-8a92-4d64-9457-f44f9f75035a", "type": "concept", "title": "Virtual life sentences"}, {"id": "b542ca0b-a704-4afb-a85e-995de8fe2fe4", "type": "concept", "title": "Juvenile life cases"}, {"id": "30023790-0a46-4170-b9b8-a8914b3bd005", "type": "concept", "title": "Parole eligibility"}, {"id": "d1233d0c-47fe-4ced-824f-625278e35f43", "type": "concept", "title": "Geriatric release"}, {"id": "6118b0b4-c9e4-4501-99a5-88f4fffe8f23", "type": "concept", "title": "Clemency"}, {"id": "5c0b9649-aa3c-43bd-ab32-729a834a33fb", "type": "concept", "